for name in RAILWAY_PROJECT RAILWAY_ENVIRONMENT RAILWAY_SERVICE APP_ORIGIN LANTERN_DB_EXPECTED_ENDPOINT LANTERN_DB_NAME LANTERN_DB_RUNTIME_ROLE LANTERN_DB_MIGRATION_ROLE LANTERN_DB_ADMIN_ROLE; do github_variable "$name" "${!name}"; done
# Use only the scoped token for subsequent webapp operations.
unset RAILWAY_API_TOKEN
export RAILWAY_TOKEN="$PRODUCTION_TOKEN"
unset PRODUCTION_TOKEN
for name in DATABASE_URL GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET APP_ORIGIN LANTERN_ENV; do railway_variable "$name" "${!name}"; done
railway_variable NODE_ENV production
railway_variable LOCAL_ACCESS 0
railway_variable LANTERN_HOSTING_ONLY 0
railway_variable HOST 0.0.0.0
unset DATABASE_URL GOOGLE_CLIENT_SECRET
step 'In the production webapp Settings: start command node dist/server/index.js; healthcheck /health; timeout 120; restart ON_FAILURE with 3 retries.'
step 'Use root Dockerfile (builder Dockerfile or Railpack); root directory /; no build override, pre-deploy command, cron, custom Railway config or independent GitHub/image source/deploy trigger.'
step 'Remove privileged BOOTSTRAP_DATABASE_URL, MIGRATION_DATABASE_URL and ADMIN_DATABASE_URL from webapp variables if present. Do not display their values.'
confirm 'Have you applied exactly those service settings and removed independent deploy triggers?' || exit 1
node "$ROOT/tools/release/configuration.mjs"

stage 'Deploy the verified main revision'
say "The workflow will migrate production schema, deploy $RELEASE_SHA, and check readiness/schema 4. Data stays separate."
confirm 'Dispatch production deployment now?' || exit 1
gh workflow run promote.yml --repo "$REPOSITORY" --ref main -f "sha=$RELEASE_SHA"
open_url "https://github.com/$REPOSITORY/actions/workflows/promote.yml"
step 'Open the run you just dispatched. Confirm its input SHA, wait for all steps to pass, and inspect its production-evidence artifact.'
warn 'If any step fails, stop; do not automatically rerun bootstrap or reset the database. Migrations are not automatically rolled back.'
confirm 'Did the exact-SHA production workflow finish successfully with matching revision and schema/readiness evidence?' || exit 1

stage 'Finish verification and private cleanup'
say 'Production now has the schema/application. No staging records have been copied.'
say 'An empty database admits nobody. Before real sign-in, use the existing access:ops domains and approve-email commands privately; production needs an approved hosted domain AND email. Set up departments only after the lead has registered.'
say 'Verify sign-in and access boundaries as owner; share only sanitized success/failure, never user records, credentials or conversation content.'
say "Keep $PRIVATE_DIR securely for separate admin/migration access; do not commit/upload it or source operator.env."
say 'Owner URL is already discarded and psql closed. Remove any temporary owner credentials/grants you created; retain only deliberately needed scoped credentials.'
confirm 'Have you reviewed retained credentials, closed owner sessions, and removed temporary grants/credentials?' || exit 1
say 'Completed: GitHub production settings, restricted Railway runtime settings, schema-only deployment and owner-reported readiness verification.'
say 'Production sign-in/enrollment requires the separate private operator actions above; readiness does not prove those flows.'
